def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def resolve_context(repo_root: str) -> dict:
    cp = subprocess.run(
        [sys.executable, str(PLUGIN_ROOT / "scripts" / "resolve-repo-context.py"),
         "--repo-root", repo_root, "--mode", "write"],
        text=True, capture_output=True, check=False, cwd=str(PLUGIN_ROOT / "scripts"),
    )
    if cp.returncode != 0:
        raise ContractError(f"C24 resolve-repo-context failed: {(cp.stderr or cp.stdout).strip()}")
    return json.loads(cp.stdout)


