def gh_auth_state() -> dict:
    cp = subprocess.run(["gh", "auth", "status"], text=True, capture_output=True, check=False)
    if cp.returncode == 0:
        return {"cli": "available", "authenticated": True}
    combined = f"{cp.stdout}{cp.stderr}".lower()
    if "not logged" in combined or "no accounts" in combined:
        return {"cli": "available", "authenticated": False}
    return {"cli": "available", "authenticated": False, "detail": "status_unavailable"}


def gh_state() -> dict:
    if shutil.which("gh") is None:
        return {"cli": "absent", "authenticated": False}
    return gh_auth_state()


def hook_wiring(root: Path, hook_source: str) -> dict:
    """plugin hook is the default; project fallback needs plain-symlink + no effective plugin hook."""
    settings = root / ".claude" / "settings.json"
    link = root / ".claude" / "dev-graph-plugin"
    existing = None
    if settings.is_file():
        existing = load_json(settings)
    fallback_events = []
    if isinstance(existing, dict):
        for event, entries in (existing.get("hooks") or {}).items():
            for entry in entries if isinstance(entries, list) else []:
                for hook in (entry or {}).get("hooks", []):
                    if "dev-graph" in str(hook.get("command", "")):
                        fallback_events.append(event)
    plugin_hooks = load_json(PLUGIN_ROOT / "hooks" / "hooks.json")
    effective_plugin_events = sorted((plugin_hooks.get("hooks") or {}).keys())
    if hook_source == "plugin":
        if fallback_events:
            raise ContractError(
                "double registration: plugin hook source requested but project fallback hooks exist: "
                f"{sorted(set(fallback_events))}"
            )
        return {
            "hook_source": "plugin",
            "effective_events": effective_plugin_events,
            "effective_paths": 1,
            "project_settings_written": False,
            "project_fallback_events": [],
            "project_plugin_link_present": link.exists() or link.is_symlink(),
            "rollback_manifest": None,
            "diagnostics": ["plugin_managed"],
        }
    raise ContractError(f"unsupported hook source for this run: {hook_source}")


def scan_forbidden(value, path="$", root: Path | None = None) -> list[str]:
    findings = []
    if isinstance(value, dict):
        for key, child in value.items():
            if any(marker in key.lower() for marker in SECRET_KEYS) and child not in (None, False):
                findings.append(f"{path}.{key}: forbidden key retains a value")
            findings.extend(scan_forbidden(child, f"{path}.{key}", root))
    elif isinstance(value, list):
        for index, child in enumerate(value):
            findings.extend(scan_forbidden(child, f"{path}[{index}]", root))
    elif isinstance(value, str):
        if value.startswith("/") or value.startswith("~") or (root and str(root) in value):
            findings.append(f"{path}: absolute path is persisted: {value}")
    return findings


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo-root", required=True)
    parser.add_argument("--hook-source", default="plugin")
    args = parser.parse_args()

    context = resolve_context(args.repo_root)
    root = Path(context["repo_root"]).resolve(strict=True)
    if root != Path(context["content_roots"]["repository"]).resolve(strict=True):
        raise ContractError("resolved repo root does not match content authority root")
    if root != Path(args.repo_root).expanduser().resolve(strict=True):
        raise ContractError("resolved repo root does not match requested --repo-root")

    planned: list[dict] = []
    created: list[str] = []
    preserved: list[str] = []
    migration_preview: list[dict] = []

    # 2. content roots + repo-local directories: create only when missing.
    for relative in [*CONTENT_ROOTS.values(), *LOCAL_DIRS]:
        target = contained(root / relative, root, must_exist=False)
        if target.is_dir():
            preserved.append(relative)
            continue
        planned.append({"action": "create_directory", "path": relative})
        target.mkdir(parents=True, exist_ok=False)
        created.append(relative)

    # 3. repo-local config and graph store: never overwrite existing content.
    config_path = root / CONFIG_REL
    desired_config = config_document(context["repository_id"], args.hook_source)
    if config_path.exists():
        current = load_json(config_path)
        if current.get("repository_id") != context["repository_id"]:
            raise ContractError("existing config repository_id does not match resolved repository")
        preserved.append(CONFIG_REL)
        if current != desired_config:
            migration_preview.append({"path": CONFIG_REL, "reason": "user_modified", "action": "preserved"})
        config_effective = current
    else:
        planned.append({"action": "create_file", "path": CONFIG_REL})
        atomic_json(config_path, desired_config)
        created.append(CONFIG_REL)
        config_effective = desired_config

    graph_path = root / GRAPH_REL
    if graph_path.exists():
        preserved.append(GRAPH_REL)
    else:
        planned.append({"action": "create_file", "path": GRAPH_REL})
        atomic_json(graph_path, INITIAL_GRAPH)
        created.append(GRAPH_REL)

    # 4. templates/: copy every plugin asset when missing, never overwrite user edits.
    templates_root = root / ".dev-graph" / "templates"
    template_files = sorted(p for p in (PLUGIN_ROOT / "templates").iterdir() if p.is_file())
    templates_report = []
    for source in template_files:
        target = contained(templates_root / source.name, root, must_exist=False)
        relative = f".dev-graph/templates/{source.name}"
        if target.exists():
            source_digest, target_digest = digest(source), digest(target)
            if source_digest == target_digest:
                preserved.append(relative)
                templates_report.append({"path": relative, "state": "preserved_identical"})
            else:
                preserved.append(relative)
                migration_preview.append({
                    "path": relative, "reason": "user_modified", "action": "preserved",
                    "plugin_digest": source_digest, "repository_digest": target_digest,
                })
                templates_report.append({"path": relative, "state": "preserved_user_modified"})
            continue
        planned.append({"action": "copy_template", "path": relative})
        shutil.copyfile(source, target)
        created.append(relative)
        templates_report.append({"path": relative, "state": "created"})

    missing_contract_assets = []
    contract = load_json(templates_root / "template-contract.json")
    declared = {contract["common_frontmatter"]["template"], contract["graph_projection"]["template"]}
    for artifact in contract["artifacts"].values():
        declared.add(artifact["template"])
        declared.update((artifact.get("subtype_templates") or {}).values())
        declared.update((artifact.get("conditional_templates") or {}).values())
    overlay = contract["system_plan"].get("task_overlay")
    if overlay:
        declared.add(overlay)
    for name in sorted(declared):
        if not (templates_root / name).is_file():
            missing_contract_assets.append(name)
    if missing_contract_assets:
        raise ContractError(f"template contract assets are missing: {missing_contract_assets}")

    # 5. hook wiring.
    hooks = hook_wiring(root, args.hook_source)

    # 6. C11 schema gate on the initial graph.
    validation = subprocess.run(
        [sys.executable, str(PLUGIN_ROOT / "scripts" / "validate-graph-schema.py"),
         "--graph", str(graph_path), "--repo-root", str(root)],
        text=True, capture_output=True, check=False, cwd=str(PLUGIN_ROOT / "scripts"),
    )
    schema_result = {
        "gate": "C11", "exit_code": validation.returncode,
        "report": json.loads(validation.stdout) if validation.stdout.strip() else None,
        "stderr": validation.stderr.strip() or None,
    }
    if validation.returncode != 0:
        raise ContractError(f"C11 schema gate failed: {schema_result}")

    forbidden = scan_forbidden(config_effective, "config", root)
    if forbidden:
        raise ContractError(f"repo config persists forbidden values: {forbidden}")

    receipt = {
        "schema_version": "1.0.0",
        "skill": "run-dev-graph-init",
        "repository_id": context["repository_id"],
        "worktree_id": context["worktree_id"],
        "root_trust_evidence": context["root_trust_evidence"],
        "content_roots": dict(CONTENT_ROOTS),
        "local_state": dict(LOCAL_STATE),
        "templates_root": ".dev-graph/templates",
        "created": sorted(created),
        "preserved": sorted(preserved),
        "migration_preview": sorted(migration_preview, key=lambda item: item["path"]),
        "templates": templates_report,
        "hook_source": hooks["hook_source"],
        "hooks": hooks,
        "github": {"enabled": False, "stored_secrets": 0, "stored_node_ids": 0},
        "gh_cli": gh_state(),
        "schema_result": {"gate": "C11", "exit_code": 0, "valid": schema_result["report"]["valid"]},
        "path_policy": {"authority": "caller-repository", "stored_paths": "repository-relative"},
    }
    atomic_json(root / RECEIPT_REL, receipt)

    print(json.dumps({
        "planned_changes": planned,
        "planned_change_count": len(planned),
        "created": sorted(created),
        "preserved_count": len(preserved),
        "migration_preview": migration_preview,
        "hooks": hooks,
        "schema_result": schema_result,
        "gh_cli": receipt["gh_cli"],
        "receipt_path": RECEIPT_REL,
        "forbidden_config_values": forbidden,
    }, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (ContractError, OSError) as exc:
        print(str(exc), file=sys.stderr)
        raise SystemExit(1)
